import{c as o,Z as l,Q as a,j as e,m as u,o as r}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"九章·橘颂","description":"","frontmatter":{"title":"九章·橘颂","author":"屈原","dynasty":"战国"},"headers":[],"relativePath":"books/shici/chuci/7.md","filePath":"books/shici/chuci/7.md"}'),q={name:"books/shici/chuci/7.md"};function h(n,t,s,c,p,d){const i=l("PoemNav");return a(),e("div",null,[t[0]||(t[0]=u('<h1 id="九章·橘颂" tabindex="-1">九章·橘颂 <a class="header-anchor" href="#九章·橘颂" aria-label="Permalink to &quot;九章·橘颂&quot;">​</a></h1><p><strong>[战国] <a href="/authors/quyuan.html">屈原</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>后皇嘉树，橘徕服兮。受命不迁，生南国兮。深固难徙，更壹志兮。绿叶素荣，纷其可喜兮。曾枝剡棘，圆果抟兮。青黄杂糅，文章烂兮。精色内白，类任道兮。纷缊宜修，姱而不丑兮。</p><p>嗟尔幼志，有以异兮。独立不迁，岂不可喜兮。深固难徙，廓其无求兮。苏世独立，横而不流兮。闭心自慎，终不失过兮。秉德无私，参天地兮。愿岁并谢，与长友兮。淑离不淫，梗其有理兮。年岁虽少，可师长兮。行比伯夷，置以为像兮。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>后皇：后土和皇天，指天地</li><li>嘉树：美好的树木</li><li>徕：通&quot;来&quot;</li><li>服：习惯</li><li>受命：受天地之命</li><li>不迁：不迁移</li><li>南国：南方</li><li>壹志：意志专一</li><li>素荣：白花</li><li>曾枝：层层枝条</li><li>剡棘：尖锐的刺</li><li>抟：通&quot;团&quot;，圆形</li><li>文章：花纹</li><li>烂：灿烂</li><li>精色：鲜明的颜色</li><li>类任道：类似能担当道义的人</li><li>纷缊：繁盛的样子</li><li>姱：美好</li><li>幼志：幼时的志向</li><li>廓：胸怀开阔</li><li>苏世：清醒地独立于世俗</li><li>横：横立，不随波逐流</li><li>闭心：静心</li><li>秉德：保持品德</li><li>参天地：与天地并立</li><li>岁并谢：与岁月一起消逝</li><li>淑离：美丽而有条理</li><li>不淫：不过分</li><li>梗：正直</li><li>伯夷：古代贤人</li><li>像：榜样</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>天地孕育的美好橘树，生来就习惯南方的水土。受命不迁移，生长在南方。根深蒂固难以移植，意志更加专一。绿叶白花，繁盛可爱。层层枝条尖刺，果实圆润。青黄相间，花纹灿烂。外表鲜明内里洁白，类似能担当道义的人。繁盛美好，美丽而不丑陋。</p><p>赞叹你幼时的志向，就与众不同。独立不迁移，难道不可喜吗？根深蒂固难以移植，胸怀开阔无所求。清醒地独立于世俗，横立而不随波逐流。静心自慎，始终不犯错误。保持品德无私，可与天地并立。愿与岁月一起消逝，与你长久为友。美丽而有条理不过分，正直而有道理。年纪虽小，可以做师长。品行可比伯夷，把你作为榜样。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首诗是《九章》中的一篇，是中国文学史上最早的咏物诗之一。屈原以橘树自喻，表达了自己忠于楚国、坚守高洁品格的决心。</p><p>第一段赞美橘树的特质。&quot;后皇嘉树，橘徕服兮&quot;，写橘树是天地孕育的美好树木。&quot;受命不迁，生南国兮&quot;，写橘树生来就不迁移，扎根南方。&quot;深固难徙，更壹志兮&quot;，写橘树根深蒂固，意志专一。这些特质，正是屈原自己所追求的。</p><p>接着赞美橘树的外表和内在。&quot;绿叶素荣&quot;&quot;曾枝剡棘&quot;&quot;青黄杂糅&quot;，写橘树的外在美。&quot;精色内白，类任道兮&quot;，写橘树外表鲜明内里洁白，象征君子外美内秀。&quot;纷缊宜修，姱而不丑兮&quot;，写橘树繁盛美好。</p><p>第二段以橘树自勉。&quot;嗟尔幼志，有以异兮&quot;，赞叹橘树幼时就与众不同。&quot;独立不迁&quot;&quot;深固难徙&quot;&quot;苏世独立&quot;&quot;横而不流&quot;，这些橘树的特质，正是屈原所追求的品格。&quot;秉德无私，参天地兮&quot;，写保持品德无私，可与天地并立。</p><p>最后&quot;愿岁并谢，与长友兮&quot;，表达了与橘树为友的愿望。&quot;行比伯夷，置以为像兮&quot;，以伯夷为榜样，表达了坚守高洁品格的决心。</p><p>全诗托物言志，以橘树的特质象征君子的品格，是中国咏物诗的典范之作。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>屈原</strong>（约公元前340年－公元前278年），名平，字原，战国时期楚国诗人、政治家。中国浪漫主义文学的奠基人，&quot;楚辞&quot;的创立者和代表作家。代表作有《离骚》《九歌》《天问》等。</p><p><a href="/authors/quyuan.html">查看作者详情 →</a></p></blockquote>',20)),r(i)])}const b=o(q,[["render",h]]);export{m as __pageData,b as default};
